Request: Define an API endpoint: GET /users with query_params limit, offset, sort, returning 200, 400. Return as JSON.

JSON Schema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "path",
    "spec"
  ],
  "properties": {
    "path": {
      "type": "string",
      "pattern": "^/[a-z0-9_/{}-]+$"
    },
    "spec": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "method",
            "responses"
          ],
          "properties": {
            "method": {
              "const": "GET"
            },
            "responses": {
              "type": "array",
              "minItems": 1,
              "items": {
                "type": "integer",
                "minimum": 100,
                "maximum": 599
              }
            },
            "query_params": {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "method",
            "body_schema",
            "responses"
          ],
          "properties": {
            "method": {
              "enum": [
                "POST",
                "PUT",
                "PATCH"
              ]
            },
            "body_schema": {
              "type": "string"
            },
            "responses": {
              "type": "array",
              "minItems": 1,
              "items": {
                "type": "integer",
                "minimum": 100,
                "maximum": 599
              }
            }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "method",
            "soft_delete"
          ],
          "properties": {
            "method": {
              "const": "DELETE"
            },
            "soft_delete": {
              "type": "boolean"
            }
          }
        }
      ]
    }
  }
}

Return only the JSON object.

{
  "path": "/users",
  "spec": {
    "method": "GET",
    "query_params": [
      "limit",
      "offset",
      "sort"
    ],
    "responses": [
      200,
      400
    ]
  }
}

Request: Describe a book: a graphic novel about a librarian on the moon. Output as JSON.

JSON Schema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "title",
    "authors",
    "isbn",
    "year",
    "genres"
  ],
  "properties": {
    "title": {
      "type": "string",
      "minLength": 1
    },
    "authors": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "minLength": 2
      }
    },
    "isbn": {
      "type": "string",
      "pattern": "^[0-9]{3}-[0-9]{10}$"
    },
    "year": {
      "type": "integer",
      "minimum": 1450,
      "maximum": 2100
    },
    "genres": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "enum": [
          "fiction",
          "non-fiction",
          "fantasy",
          "sci-fi",
          "mystery",
          "biography",
          "history",
          "science",
          "philosophy",
          "poetry"
        ]
      },
      "uniqueItems": true
    },
    "page_count": {
      "type": "integer",
      "minimum": 1
    }
  }
}

Return only the JSON object.

