  "type": "object",
  "additionalProperties": false,
  "required": [
    "invoice_id",
    "customer",
    "line_items",
    "total",
    "currency"
  ],
  "properties": {
    "invoice_id": {
      "type": "string",
      "pattern": "^INV-[0-9]{6}$"
    },
    "customer": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "email"
      ],
      "properties": {
        "name": {
          "type": "string",
          "minLength": 2
        },
        "email": {
          "type": "string",
          "format": "email"
        },
        "vat": {
          "type": "string"
        }
      }
    },
    "line_items": {
      "type": "array",
      "minItems": 1,
      "maxItems": 20,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "sku",
          "qty",
          "unit_price"
        ],
        "properties": {
          "sku": {
            "type": "string",
            "pattern": "^[A-Z]{3}-[0-9]{3,5}$"
          },
          "qty": {
            "type": "integer",
            "minimum": 1
          },
          "unit_price": {
            "type": "number",
            "exclusiveMinimum": 0
          }
        }
      }
    },
    "total": {
      "type": "number",
      "minimum": 0
    },
    "currency": {
      "type": "string",
      "enum": [
        "USD",
        "EUR",
        "GBP",
        "JPY",
        "CAD"
      ]
    },
    "issued": {
      "type": "string",
      "format": "date"
    }
  }
}

Return only the JSON object.

