          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "method",
            "body_schema",
            "responses"
          ],
          "properties": {
            "method": {
              "enum": [
                "POST",
                "PUT",
                "PATCH"
              ]
            },
            "body_schema": {
              "type": "string"
            },
            "responses": {
              "type": "array",
              "minItems": 1,
              "items": {
                "type": "integer",
                "minimum": 100,
                "maximum": 599
              }
            }
          }
        },
        {
